        radius: arg.radius,
        plus: plus.size,
        minus: minus.size,
        gegenstrom: 2 * Math.min(plus.size, minus.size),
        geher: geher.size,
        maxGleich,
        zeit,
        ordnung: spaet.length ? +(spaet.reduce((x, y) => x + y, 0) / spaet.length).toFixed(3) : null,
        phi: phi.map((x) => (x == null ? null : +x.toFixed(2))),
